//! 🧪️ Original typed descriptor fields keep their native allocations until their separately paid retirement turn.
use super::*;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress};
use semio_framework_value::retirement::queue::RetirementQueue;
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn manifest_argument_retirement_original_typed_fields_preserve_denied_pointers_and_physical_receipts(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["policy"];let grant=RetainedCloneGrant{maximum_items:p["items"].as_u64().unwrap()as usize,maximum_copy_bytes:p["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:p["release"].as_u64().unwrap()as usize,maximum_depth:p["depth"].as_u64().unwrap()as usize};
 let((original,pointer,bytes),birth)=observe(||{let text=law["strings"][0].as_str().unwrap();let de=law["strings"][1].as_str().unwrap();let mut id=String::with_capacity(65536);id.push_str(text);let pointer=id.as_ptr();let bytes=id.len();let label=LocalizedLabel::native(text,de);let mut string=ActionArgDef::with_schema(id,label.clone(),ArgSchema::String{options:vec![ActionArgOption::new(text,label.clone())],option_source:Some(OptionSource::Snapshot{pointer:"/original-options".into()}),min_len:Some(0),max_len:Some(65536),pattern:Some("original.*".into()),format:Some(ArgFormat::SurfaceApp{roles:vec![AppRole::Viewer,AppRole::Editor],dialect_arg:text.into()})});string.default=Some(DslValue::String(de.into()));string.description=Some(label.clone());string.group=Some(text.into());string.presentation=Some(ArgPresentation::IconSelect{classifier_kind:text.into()});let mut number=ActionArgDef::number(text,label.clone());if let ArgSchema::Number{snaps,snap_source,scale,..}=&mut number.schema{*snaps=vec![0.0,1.0];*snap_source=Some(SnapSource::Config{key:text.into()});*scale=Some(NumberScale::Log);}let mut reference=ActionArgDef::text(text,label);reference.schema=ArgSchema::Reference{kinds:vec![text.into()],domain:Some(text.into()),granularity:Some(text.into()),many:true,min_items:None,max_items:None,id_type:ReferenceIdType::Integer};let args=ArgSchema::Array{items:Box::new(ArgSchema::Object{fields:vec![string,number,reference]}),min_items:Some(0),max_items:Some(3)};let error=InputSchemaError{code:InputSchemaErrorCode::RefUnresolved,pointer:"/original".into(),detail:de.into()};((args,error),pointer,bytes)});
 eprintln!("[DEBUG] original Manifest input native birth={} release={} idpointer={pointer:p} idbytes={bytes}",birth.0,birth.1);
 let mut cursor=RetirementQueue::default();let mut metadata=(0,0);let mut reservations=0;while !cursor.has_reserved_slot(){reservations+=1;assert!(reservations<=8);let(capacity,heap)=observe(||cursor.next_reserve_capacity_byte_demand().unwrap());assert_eq!(heap,(0,0));assert!(capacity<=grant.maximum_capacity_bytes);for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_capacity_bytes:capacity.saturating_sub(1),..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,heap)=observe(||cursor.reserve_step(denied));if let Ok(progress)=result{assert_eq!(progress,RetainedCloneProgress::default());}assert_eq!(heap,(0,0));assert!(!cursor.has_reserved_slot());assert_eq!(unsafe{std::slice::from_raw_parts(pointer,bytes)},law["strings"][0].as_str().unwrap().as_bytes());}let(reservation,heap)=observe(||cursor.reserve_step(grant).unwrap());eprintln!("[DEBUG] Manifest original reservation={reservations} receipt={reservation:?} actual={heap:?}");assert!(reservation.fits(grant));assert_eq!((reservation.retained_capacity_bytes,reservation.released_bytes),heap);assert_eq!(reservation.copied_items,1);metadata.0+=heap.0;metadata.1+=heap.1;}let(admission,frame)=observe(||cursor.admit_owned(original,grant).map_err(|(error,_)|error).unwrap());eprintln!("[DEBUG] Manifest admission receipt={admission:?} actual={frame:?}");assert!(admission.fits(grant));assert_eq!((admission.retained_capacity_bytes,admission.released_bytes),frame);assert_eq!(unsafe{std::slice::from_raw_parts(pointer,bytes)},law["strings"][0].as_str().unwrap().as_bytes());
 let mut allocated=birth.0+metadata.0+frame.0;let mut released=birth.1+metadata.1+frame.1;let mut turns=0;while !cursor.terminal_is_empty(){turns+=1;assert!(turns<8192);let((copy,capacity,release,depth),heap)=observe(||(cursor.next_copy_byte_demand().unwrap(),cursor.next_capacity_byte_demand(grant.maximum_copy_bytes).unwrap(),cursor.next_release_byte_demand().unwrap(),cursor.next_depth_demand().unwrap()));assert_eq!(heap,(0,0));for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(copy>0).then_some(RetainedCloneGrant{maximum_copy_bytes:copy.saturating_sub(1),..grant}),(capacity>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:capacity.saturating_sub(1),..grant}),(release>0).then_some(RetainedCloneGrant{maximum_release_bytes:release.saturating_sub(1),..grant}),(depth>0).then_some(RetainedCloneGrant{maximum_depth:depth.saturating_sub(1),..grant})].into_iter().flatten(){let(step,heap)=observe(||cursor.step(denied));if let Ok(step)=step{assert_eq!(step.progress(),RetainedCloneProgress::default());}assert_eq!(heap,(0,0));if turns==1{assert_eq!(unsafe{std::slice::from_raw_parts(pointer,bytes)},law["strings"][0].as_str().unwrap().as_bytes());}}let(step,heap)=observe(||cursor.step(grant).unwrap());let progress=step.progress();eprintln!("[DEBUG] Manifest original turn={turns} demand=({copy},{capacity},{release},{depth}) receipt={progress:?} actual={heap:?}");assert!(progress.fits(grant));assert_eq!((progress.retained_capacity_bytes,progress.released_bytes),heap);allocated+=heap.0;released+=heap.1;}
 let(_,heap)=observe(||drop(cursor));assert_eq!(heap,(0,0));assert_eq!(allocated,released);eprintln!("[DEBUG] actual original Manifest12 transitive typed descriptor owners EN/DE turns={turns} original field pointer retained on denied axes original id capacity65536 funded physical={} terminalDrop0 fixedbody4096",released);
}
